const fs = require('fs');

function main() {
  let raw;
  try {
    raw = fs.readFileSync(0, 'utf8');
  } catch (e) {
    raw = fs.readFileSync('/dev/stdin', 'utf8');
  }
  const data = raw.trim().split(/\s+/).map(Number);
  let p = 0;
  const sx = data[p++], sy = data[p++], tx = data[p++], ty = data[p++];
  const N = data[p++];
  const M = N + 2; // node 0 = início, 1..N = retângulos, M-1 = destino

  const X1 = new Int32Array(M), Y1 = new Int32Array(M);
  const X2 = new Int32Array(M), Y2 = new Int32Array(M);

  // início e destino como retângulos degenerados (pontos)
  X1[0] = X2[0] = sx; Y1[0] = Y2[0] = sy;
  for (let i = 1; i <= N; i++) {
    const a = data[p++], b = data[p++], c = data[p++], d = data[p++];
    X1[i] = a < c ? a : c; X2[i] = a < c ? c : a;
    Y1[i] = b < d ? b : d; Y2[i] = b < d ? d : b;
  }
  X1[M - 1] = X2[M - 1] = tx; Y1[M - 1] = Y2[M - 1] = ty;

  const dist = new Float64Array(M).fill(Infinity);
  const done = new Uint8Array(M);
  dist[0] = 0;
  const last = M - 1;

  // Dijkstra O(V^2) sobre grafo completo
  // peso(a,b) = distância L1 (lacuna) entre os conjuntos: max(0, falha em x) + max(0, falha em y)
  for (;;) {
    let u = -1, bd = Infinity;
    for (let v = 0; v < M; v++) {
      if (!done[v] && dist[v] < bd) { bd = dist[v]; u = v; }
    }
    if (u < 0 || u === last) break;
    done[u] = 1;
    const ax1 = X1[u], ax2 = X2[u], ay1 = Y1[u], ay2 = Y2[u];
    for (let v = 0; v < M; v++) {
      if (done[v]) continue;
      let w = 0;
      if (X1[v] > ax2) w = X1[v] - ax2;
      else if (ax1 > X2[v]) w = ax1 - X2[v];
      if (Y1[v] > ay2) w += Y1[v] - ay2;
      else if (ay1 > Y2[v]) w += ay1 - Y2[v];
      const nd = bd + w;
      if (nd < dist[v]) dist[v] = nd;
    }
  }

  console.log(Math.round(dist[last]));
}

main();
